/**
 * Returns a composite SVG ribbon containing the 4 official logos (Google Pay, PhonePe, Paytm, UPI)
 * side-by-side on a transparent background, formatted for high-res HTML5 Canvas drawing.
 */
export function getUpiBrandRibbonSvg({ width = 480, height = 30 } = {}) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 480 30">
    <g transform="translate(15, 2)">
      <svg x="0" y="0" width="60" height="26" viewBox="7.5 11.5 42 19" preserveAspectRatio="xMidYMid meet">${GOOGLE_PAY_SVG_HTML.replace(/^<svg[^>]+>/, '').replace(/<\/svg>$/, '')}</svg>
      <svg x="110" y="0" width="95" height="26" viewBox="200 245 965 275" preserveAspectRatio="xMidYMid meet">${PHONEPE_SVG_HTML.replace(/^<svg[^>]+>/, '').replace(/<\/svg>$/, '')}</svg>
      <svg x="250" y="0" width="75" height="26" viewBox="-155 208 496 178" preserveAspectRatio="xMidYMid meet">${PAYTM_SVG_HTML.replace(/^<svg[^>]+>/, '').replace(/<\/svg>$/, '')}</svg>
      <svg x="365" y="0" width="78" height="26" viewBox="85 80 855 308" preserveAspectRatio="xMidYMid meet">${UPI_SVG_HTML.replace(/^<svg[^>]+>/, '').replace(/<\/svg>$/, '')}</svg>
    </g>
  </svg>`
}

/**
 * Loads all 4 official brand logos (Google Pay, PhonePe, Paytm, UPI) as HTMLImageElements,
 * plus composite ribbonImg, for high-res Canvas rendering and PNG export.
 * Uses both Blob URLs and encoded Data URIs as resilient fallback.
 */
export async function loadUpiBrandLogos() {
  const loadSingleSvgImg = (svgString, fallbackAssetUrl = null) => {
    return new Promise((resolve) => {
      let settled = false
      const finish = (img, url) => {
        if (!settled) {
          settled = true
          resolve({ img, url })
        }
      }

      try {
        const blob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' })
        const url = URL.createObjectURL(blob)
        const img = new Image()
        img.crossOrigin = 'anonymous'
        img.onload = () => finish(img, url)
        img.onerror = () => {
          try {
            const dataUrl = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svgString)}`
            const fallbackImg = new Image()
            fallbackImg.crossOrigin = 'anonymous'
            fallbackImg.onload = () => finish(fallbackImg, url)
            fallbackImg.onerror = () => {
              if (fallbackAssetUrl) {
                const assetImg = new Image()
                assetImg.crossOrigin = 'anonymous'
                assetImg.onload = () => finish(assetImg, url)
                assetImg.onerror = () => finish(null, url)
                assetImg.src = fallbackAssetUrl
              } else {
                finish(null, url)
              }
            }
            fallbackImg.src = dataUrl
          } catch {
            if (fallbackAssetUrl) {
              const assetImg = new Image()
              assetImg.crossOrigin = 'anonymous'
              assetImg.onload = () => finish(assetImg, url)
              assetImg.onerror = () => finish(null, url)
              assetImg.src = fallbackAssetUrl
            } else {
              finish(null, url)
            }
          }
        }
        img.src = url
      } catch {
        if (fallbackAssetUrl) {
          const assetImg = new Image()
          assetImg.crossOrigin = 'anonymous'
          assetImg.onload = () => finish(assetImg, null)
          assetImg.onerror = () => finish(null, null)
          assetImg.src = fallbackAssetUrl
        } else {
          finish(null, null)
        }
      }
    })
  }

  const ribbonSvg = getUpiBrandRibbonSvg({ width: 440, height: 28 })

  const [gpay, phonepe, paytm, upi, ribbon] = await Promise.all([
    loadSingleSvgImg(GOOGLE_PAY_SVG_HTML, gpayAssetUrl),
    loadSingleSvgImg(PHONEPE_SVG_HTML, phonepeAssetUrl),
    loadSingleSvgImg(PAYTM_SVG_HTML, paytmAssetUrl),
    loadSingleSvgImg(UPI_SVG_HTML, upiAssetUrl),
    loadSingleSvgImg(ribbonSvg, null),
  ])

  return {
    gpayImg: gpay.img,
    phonepeImg: phonepe.img,
    paytmImg: paytm.img,
    upiImg: upi.img,
    ribbonImg: ribbon.img,
    cleanup: () => {
      if (gpay.url) URL.revokeObjectURL(gpay.url)
      if (phonepe.url) URL.revokeObjectURL(phonepe.url)
      if (paytm.url) URL.revokeObjectURL(paytm.url)
      if (upi.url) URL.revokeObjectURL(upi.url)
      if (ribbon.url) URL.revokeObjectURL(ribbon.url)
    },
  }
}

